le_size']/1024,1) ?> KB</div><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Verified recovery copy is ready</h2><p>SHA-256: <code><?= backup_step18_h($created['file_sha256']) ?></code></p></div><a class="os-btn primary" href="backup_download.php?id=<?= (int)$created['id'] ?>">Download .hwcbak</a></div></section><?php endif;?><section class="s10-grid" style="margin-top:14px"><article class="s10-card s10-span-8"><h2>New Manual Backup</h2><form method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?= backup_step18_h($csrf??'') ?>"><label style="display:block;font-weight:800;margin-top:10px">Backup Passphrase<input type="password" name="passphrase" required autocomplete="new-password" minlength="12" style="width:100%;box-sizing:border-box;margin-top:6px;padding:12px;border:1px solid #cedbd2;border-radius:12px"></label><label style="display:block;font-weight:800;margin-top:14px">Confirm Passphrase<input type="password" name="confirm_passphrase" required autocomplete="new-password" minlength="12" style="width:100%;box-sizing:border-box;margin-top:6px;padding:12px;border:1px solid #cedbd2;border-radius:12px"></label><label style="display:block;font-weight:800;margin-top:14px">Notes (optional)<textarea name="notes" maxlength="1000" rows="3" style="width:100%;box-sizing:border-box;margin-top:6px;padding:12px;border:1px solid #cedbd2;border-radius:12px" placeholder="Example: Before monthly closing"></textarea></label><button class="os-btn primary" style="margin-top:16px" type="submit">Create & Verify Encrypted Backup</button></form></article><aside class="s10-card s10-span-4"><h2>Passphrase Safety</h2><div class="s10-list"><div class="s10-row"><div><b>Minimum</b><small>At least 12 characters.</small></div></div><div class="s10-row"><div><b>Never stored</b><small>The server does not keep a recoverable copy.</small></div></div><div class="s10-row"><div><b>Keep separately</b><small>Store it in a trusted password manager or offline recovery record.</small></div></div><div class="s10-row"><div><b>Verification</b><small>The package is decrypted and authenticated immediately after creation.</small></div></div></div></aside></section></main></div></body></html>